INSERT INTO changelog (title, body, created_at) VALUES ('Стратегія: нормальна картка «Куди йдемо»', 'Ціль зверху Стратегії тепер повноцінна картка: видно до 3 рядків тексту (а не один обрізаний рядок), кнопка «Змінити». Вікно правки — широке, з великим полем під довгий текст і диктуванням.', datetime('now'));
